/// Strongly typed models for Classical Vedic Yoga evaluation responses
/// Generated by packages/astrology-engine deterministic Yoga Calculator.
library;

class YogaConditionModel {
  final String id;
  final String description;
  final bool satisfied;
  final dynamic expected;
  final dynamic observed;

  const YogaConditionModel({
    required this.id,
    required this.description,
    required this.satisfied,
    required this.expected,
    required this.observed,
  });

  factory YogaConditionModel.fromJson(Map<String, dynamic> json) {
    return YogaConditionModel(
      id: json['id'] as String? ?? '',
      description: json['description'] as String? ?? '',
      satisfied: json['satisfied'] as bool? ?? false,
      expected: json['expected'],
      observed: json['observed'],
    );
  }
}

class YogaPlanetEvidenceModel {
  final String planet;
  final int rashiIndex;
  final String rashiName;
  final int house;
  final double longitude;
  final double degreeInRashi;
  final String dignity;
  final bool isCombust;
  final bool isRetrograde;

  const YogaPlanetEvidenceModel({
    required this.planet,
    required this.rashiIndex,
    required this.rashiName,
    required this.house,
    required this.longitude,
    required this.degreeInRashi,
    required this.dignity,
    required this.isCombust,
    required this.isRetrograde,
  });

  factory YogaPlanetEvidenceModel.fromJson(Map<String, dynamic> json) {
    return YogaPlanetEvidenceModel(
      planet: json['planet'] as String? ?? '',
      rashiIndex: (json['rashiIndex'] as num?)?.toInt() ?? 1,
      rashiName: json['rashiName'] as String? ?? '',
      house: (json['house'] as num?)?.toInt() ?? 1,
      longitude: (json['longitude'] as num?)?.toDouble() ?? 0.0,
      degreeInRashi: (json['degreeInRashi'] as num?)?.toDouble() ?? 0.0,
      dignity: json['dignity'] as String? ?? 'NEUTRAL',
      isCombust: json['isCombust'] as bool? ?? false,
      isRetrograde: json['isRetrograde'] as bool? ?? false,
    );
  }
}

class YogaHouseEvidenceModel {
  final int houseNumber;
  final int rashiIndex;
  final String rashiName;
  final String lord;
  final List<String> occupyingPlanets;

  const YogaHouseEvidenceModel({
    required this.houseNumber,
    required this.rashiIndex,
    required this.rashiName,
    required this.lord,
    required this.occupyingPlanets,
  });

  factory YogaHouseEvidenceModel.fromJson(Map<String, dynamic> json) {
    final occ = (json['occupyingPlanets'] as List? ?? []).map((e) => e.toString()).toList();
    return YogaHouseEvidenceModel(
      houseNumber: (json['houseNumber'] as num?)?.toInt() ?? 1,
      rashiIndex: (json['rashiIndex'] as num?)?.toInt() ?? 1,
      rashiName: json['rashiName'] as String? ?? '',
      lord: json['lord'] as String? ?? '',
      occupyingPlanets: occ,
    );
  }
}

class YogaRelationshipEvidenceModel {
  final String relationshipType;
  final List<String> planets;
  final List<int> houses;
  final String description;

  const YogaRelationshipEvidenceModel({
    required this.relationshipType,
    required this.planets,
    required this.houses,
    required this.description,
  });

  factory YogaRelationshipEvidenceModel.fromJson(Map<String, dynamic> json) {
    final pList = (json['planets'] as List? ?? []).map((e) => e.toString()).toList();
    final hList = (json['houses'] as List? ?? []).map((e) => (e as num).toInt()).toList();
    return YogaRelationshipEvidenceModel(
      relationshipType: json['relationshipType'] as String? ?? '',
      planets: pList,
      houses: hList,
      description: json['description'] as String? ?? '',
    );
  }
}

class YogaEvidenceModel {
  final List<YogaConditionModel> conditions;
  final List<YogaPlanetEvidenceModel> involvedPlanets;
  final List<YogaHouseEvidenceModel> involvedHouses;
  final List<YogaRelationshipEvidenceModel> relationships;
  final List<String> strengthFactors;

  const YogaEvidenceModel({
    this.conditions = const [],
    this.involvedPlanets = const [],
    this.involvedHouses = const [],
    this.relationships = const [],
    this.strengthFactors = const [],
  });

  factory YogaEvidenceModel.fromJson(Map<String, dynamic> json) {
    final cList = (json['conditions'] as List? ?? [])
        .whereType<Map>()
        .map((c) => YogaConditionModel.fromJson(Map<String, dynamic>.from(c)))
        .toList();

    final pList = (json['involvedPlanets'] as List? ?? [])
        .whereType<Map>()
        .map((p) => YogaPlanetEvidenceModel.fromJson(Map<String, dynamic>.from(p)))
        .toList();

    final hList = (json['involvedHouses'] as List? ?? [])
        .whereType<Map>()
        .map((h) => YogaHouseEvidenceModel.fromJson(Map<String, dynamic>.from(h)))
        .toList();

    final rList = (json['relationships'] as List? ?? [])
        .whereType<Map>()
        .map((r) => YogaRelationshipEvidenceModel.fromJson(Map<String, dynamic>.from(r)))
        .toList();

    final sList = (json['strengthFactors'] as List? ?? []).map((e) => e.toString()).toList();

    return YogaEvidenceModel(
      conditions: cList,
      involvedPlanets: pList,
      involvedHouses: hList,
      relationships: rList,
      strengthFactors: sList,
    );
  }
}

class YogaResultModel {
  final String id;
  final String canonicalName;
  final String sanskritName;
  final String category;
  final bool isDetected;
  final String varga;
  final String convention;
  final YogaEvidenceModel evidence;

  const YogaResultModel({
    required this.id,
    required this.canonicalName,
    required this.sanskritName,
    required this.category,
    required this.isDetected,
    required this.varga,
    required this.convention,
    required this.evidence,
  });

  factory YogaResultModel.fromJson(Map<String, dynamic> json) {
    return YogaResultModel(
      id: json['id'] as String? ?? '',
      canonicalName: json['canonicalName'] as String? ?? json['name'] as String? ?? 'Classical Yoga',
      sanskritName: json['sanskritName'] as String? ?? '',
      category: (json['category'] as String? ?? 'MISCELLANEOUS').toUpperCase(),
      isDetected: json['isDetected'] as bool? ?? json['detected'] as bool? ?? true,
      varga: json['varga'] as String? ?? 'D1',
      convention: json['convention'] as String? ?? 'PARASHARI',
      evidence: json['evidence'] is Map
          ? YogaEvidenceModel.fromJson(Map<String, dynamic>.from(json['evidence']))
          : const YogaEvidenceModel(),
    );
  }

  String get formattedCategory {
    switch (category) {
      case 'MAHAPURUSHA': return 'Pancha Mahapurusha';
      case 'RAJA': return 'Raja Yoga';
      case 'DHANA': return 'Dhana (Wealth) Yoga';
      case 'CHANDRA': return 'Chandra (Lunar) Yoga';
      case 'SURYA': return 'Surya (Solar) Yoga';
      case 'NEECHA_BHANGA': return 'Neecha Bhanga Raja Yoga';
      case 'PARIVARTANA': return 'Parivartana (Mutual Exchange)';
      case 'VIPARITA': return 'Viparita Raja Yoga';
      case 'NABHASA': return 'Nabhasa (Celestial Formation)';
      case 'AUSPICIOUS': return 'Shubha (Auspicious) Yoga';
      case 'INAUSPICIOUS': return 'Ashubha (Inauspicious) Yoga';
      default: return category;
    }
  }

  List<String> get planetNames {
    if (evidence.involvedPlanets.isNotEmpty) {
      return evidence.involvedPlanets.map((p) => p.planet).toSet().toList();
    }
    return [];
  }

  List<int> get houseNumbers {
    if (evidence.involvedHouses.isNotEmpty) {
      return evidence.involvedHouses.map((h) => h.houseNumber).toSet().toList();
    }
    return [];
  }
}

class YogaEvaluationReportModel {
  final String calculationVersion;
  final String varga;
  final int totalEvaluated;
  final int detectedCount;
  final List<YogaResultModel> detectedYogas;
  final List<YogaResultModel> undetectedYogas;

  const YogaEvaluationReportModel({
    required this.calculationVersion,
    required this.varga,
    required this.totalEvaluated,
    required this.detectedCount,
    required this.detectedYogas,
    this.undetectedYogas = const [],
  });

  factory YogaEvaluationReportModel.fromJson(Map<String, dynamic> json) {
    final root = json['data'] is Map<String, dynamic>
        ? json['data'] as Map<String, dynamic>
        : json;

    final rawDetected = root['detectedYogas'] as List? ?? root['yogas'] as List? ?? [];
    final rawUndetected = root['undetectedYogas'] as List? ?? [];

    final detected = rawDetected
        .whereType<Map>()
        .map((y) => YogaResultModel.fromJson(Map<String, dynamic>.from(y)))
        .toList();

    final undetected = rawUndetected
        .whereType<Map>()
        .map((y) => YogaResultModel.fromJson(Map<String, dynamic>.from(y)))
        .toList();

    return YogaEvaluationReportModel(
      calculationVersion: root['calculationVersion'] as String? ?? '1.0.0',
      varga: root['varga'] as String? ?? 'D1',
      totalEvaluated: (root['totalEvaluated'] as num?)?.toInt() ?? (detected.length + undetected.length),
      detectedCount: (root['detectedCount'] as num?)?.toInt() ?? detected.length,
      detectedYogas: detected,
      undetectedYogas: undetected,
    );
  }
}
